import{_ as t,o as n,c as a,a2 as s}from"./chunks/framework.5akMI7mQ.js";const g=JSON.parse('{"title":"Resource Limits & Isolation","description":"","frontmatter":{},"headers":[],"relativePath":"production/resource-limits.md","filePath":"production/resource-limits.md","lastUpdated":1792429063000}'),i={name:"production/resource-limits.md"};function o(r,e,l,d,c,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="resource-limits-isolation" tabindex="-1">Resource Limits &amp; Isolation <a class="header-anchor" href="#resource-limits-isolation" aria-label="Permalink to &quot;Resource Limits &amp; Isolation&quot;">​</a></h1><p><strong>Wednes Serverless Engine</strong> implements a <strong>3-tier defense-in-depth isolation architecture</strong> to prevent untrusted guest code or saturated endpoints from degrading the host system or starving adjacent functions.</p><hr><h2 id="the-3-tier-enforcement-model" tabindex="-1">The 3-Tier Enforcement Model <a class="header-anchor" href="#the-3-tier-enforcement-model" aria-label="Permalink to &quot;The 3-Tier Enforcement Model&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Tier 1: Linux Host &amp; cgroups v2</span></span>
<span class="line"><span> ┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │  - systemd / Docker MemoryMax (e.g. 1800MB)                 │</span></span>
<span class="line"><span> │  - CPUQuota (e.g. 200%)                                     │</span></span>
<span class="line"><span> │  - LimitNOFILE (e.g. 65536)                                 │</span></span>
<span class="line"><span> └──────────────────────────────┬──────────────────────────────┘</span></span>
<span class="line"><span>                                │</span></span>
<span class="line"><span> Tier 2: Gateway Admission &amp; Schedulers</span></span>
<span class="line"><span> ┌──────────────────────────────▼──────────────────────────────┐</span></span>
<span class="line"><span> │  - Global Concurrency Semaphore (--global-concurrency 200)  │</span></span>
<span class="line"><span> │  - Per-Function Concurrency (--default-concurrency 16)      │</span></span>
<span class="line"><span> │  - Host Memory Budget Check (--memory-budget-mb 1536)       │</span></span>
<span class="line"><span> └──────────────────────────────┬──────────────────────────────┘</span></span>
<span class="line"><span>                                │</span></span>
<span class="line"><span> Tier 3: Wasmtime Sandboxed Runtime</span></span>
<span class="line"><span> ┌──────────────────────────────▼──────────────────────────────┐</span></span>
<span class="line"><span> │  - StoreLimits: per-invocation linear memory ceiling (32MB) │</span></span>
<span class="line"><span> │  - Epoch Timer: deterministic execution deadline (250ms)    │</span></span>
<span class="line"><span> │  - Closed WASI World: zero host filesystem / socket leakage │</span></span>
<span class="line"><span> └─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_1-gateway-admission-tier-2" tabindex="-1">1. Gateway Admission (Tier 2) <a class="header-anchor" href="#_1-gateway-admission-tier-2" aria-label="Permalink to &quot;1. Gateway Admission (Tier 2)&quot;">​</a></h2><p>Before any WebAssembly instance is allocated, incoming requests pass through the gateway <code>Scheduler</code>:</p><ul><li><strong>Global Semaphore:</strong> Limits total in-flight requests across all functions. When saturated, incoming requests immediately receive <code>HTTP 429 Too Many Requests</code>.</li><li><strong>Per-Function Semaphore:</strong> Configured via <code>runtime.max_concurrency</code> in <code>wednes.yaml</code>. Prevents an aggressive webhook caller from consuming all available execution threads.</li><li><strong>Memory Admission:</strong> Verifies that allocating the function&#39;s maximum requested memory will not breach the daemon&#39;s <code>--memory-budget-mb</code>.</li></ul><hr><h2 id="_2-runtime-sandboxing-tier-3" tabindex="-1">2. Runtime Sandboxing (Tier 3) <a class="header-anchor" href="#_2-runtime-sandboxing-tier-3" aria-label="Permalink to &quot;2. Runtime Sandboxing (Tier 3)&quot;">​</a></h2><h3 id="linear-memory-bounding-storelimits" tabindex="-1">Linear Memory Bounding (<code>StoreLimits</code>) <a class="header-anchor" href="#linear-memory-bounding-storelimits" aria-label="Permalink to &quot;Linear Memory Bounding (\`StoreLimits\`)&quot;">​</a></h3><p>Each invocation operates in its own newly allocated <code>wasmtime::Store</code>. Linear memory allocation is governed by Wasmtime&#39;s <code>StoreLimits</code>:</p><ul><li>If guest code attempts to allocate past its configured <code>memory_mb</code>, the memory growth operation returns an allocation failure or triggers a trap.</li><li>The trap is caught by the daemon; the invocation returns an HTTP error response to the client.</li><li><strong>The host daemon process does not crash or leak memory.</strong></li></ul><h3 id="execution-deadline-trapping-epoch-interruption" tabindex="-1">Execution Deadline Trapping (Epoch Interruption) <a class="header-anchor" href="#execution-deadline-trapping-epoch-interruption" aria-label="Permalink to &quot;Execution Deadline Trapping (Epoch Interruption)&quot;">​</a></h3><p>To neutralize infinite loops, regex catastrophic backtracking, or heavy compute deadlocks:</p><ul><li>A background thread advances Wasmtime&#39;s epoch engine at fixed intervals (e.g., every 10 milliseconds).</li><li>Each invocation is configured with an epoch deadline computed from <code>timeout_ms</code>.</li><li>When the deadline expires, the Cranelift JIT engine traps out of execution immediately.</li><li>The trapped guest instance is dropped, reclaiming resources.</li></ul><hr><h2 id="failure-behavior-matrix" tabindex="-1">Failure Behavior Matrix <a class="header-anchor" href="#failure-behavior-matrix" aria-label="Permalink to &quot;Failure Behavior Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Scenario</th><th style="text-align:left;">Trigger / Mechanism</th><th style="text-align:center;">HTTP Status</th><th style="text-align:left;">Impact on Daemon</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Memory Exhaustion</strong></td><td style="text-align:left;">Guest allocates &gt; <code>memory_mb</code></td><td style="text-align:center;"><code>500 Internal Error</code></td><td style="text-align:left;">Trapped cleanly. Zero host leakage.</td></tr><tr><td style="text-align:left;"><strong>Infinite Loop</strong></td><td style="text-align:left;">Execution runs &gt; <code>timeout_ms</code></td><td style="text-align:center;"><code>500 Internal Error</code></td><td style="text-align:left;">Trapped via Epoch timer. Normal operation resumes.</td></tr><tr><td style="text-align:left;"><strong>High Traffic Spike</strong></td><td style="text-align:left;">Concurrent requests &gt; semaphore</td><td style="text-align:center;"><code>429 Too Many Requests</code></td><td style="text-align:left;">Fast rejection without invoking Wasmtime.</td></tr><tr><td style="text-align:left;"><strong>Invalid WASM Bytecode</strong></td><td style="text-align:left;">Missing WIT export or malformed ABI</td><td style="text-align:center;">Rejected at <code>deploy</code></td><td style="text-align:left;">Registry rollback; unchanged live state.</td></tr></tbody></table><hr><h2 id="sizing-guidelines-by-node-capacity" tabindex="-1">Sizing Guidelines by Node Capacity <a class="header-anchor" href="#sizing-guidelines-by-node-capacity" aria-label="Permalink to &quot;Sizing Guidelines by Node Capacity&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Server Specs</th><th style="text-align:center;">Suggested <code>--global-concurrency</code></th><th style="text-align:center;">Suggested <code>--memory-budget-mb</code></th><th style="text-align:center;">Per-Function Default <code>memory_mb</code></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1 vCPU / 1 GB RAM</strong></td><td style="text-align:center;"><code>50</code></td><td style="text-align:center;"><code>650</code></td><td style="text-align:center;"><code>16 - 32 MB</code></td></tr><tr><td style="text-align:left;"><strong>2 vCPU / 2 GB RAM</strong></td><td style="text-align:center;"><code>150</code></td><td style="text-align:center;"><code>1400</code></td><td style="text-align:center;"><code>32 - 64 MB</code></td></tr><tr><td style="text-align:left;"><strong>4 vCPU / 8 GB RAM</strong></td><td style="text-align:center;"><code>600</code></td><td style="text-align:center;"><code>6000</code></td><td style="text-align:center;"><code>64 - 128 MB</code></td></tr><tr><td style="text-align:left;"><strong>8 vCPU / 16 GB RAM</strong></td><td style="text-align:center;"><code>1500</code></td><td style="text-align:center;"><code>12000</code></td><td style="text-align:center;"><code>128 - 256 MB</code></td></tr></tbody></table>`,23)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
